
"""
测试长评爬取逻辑，用本地的《将来的事》影评列表页测试前5条
"""
import sys
import os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import json
from bs4 import BeautifulSoup
from crawler.parser import parse_review_full

def main():
    print("="*80)
    print("🎬 测试长评爬取解析逻辑")
    print("="*80)
    
    # 1. 读取本地影评列表页HTML
    html_path = r"e:\QuartEdition\BackEnd\data\将来的事的影评 (476).html"
    with open(html_path, 'r', encoding='utf-8') as f:
        list_html = f.read()
    
    # 2. 解析列表页，提取前5条review_id和标题
    soup = BeautifulSoup(list_html, "lxml")
    review_items = soup.select("div.review-item")[:5]
    
    print(f"\n✅ 提取到前{len(review_items)}条长评：")
    print("-"*80)
    
    test_reviews = []
    for idx, item in enumerate(review_items, 1):
        review_id = item.get("id", "").split("-")[-1]
        title = item.select_one("h2 a").get_text(strip=True) if item.select_one("h2 a") else "无标题"
        author = item.select_one("a.name").get_text(strip=True) if item.select_one("a.name") else "匿名"
        
        print(f"{idx}. review_id={review_id}, 标题={title}, 作者={author}")
        test_reviews.append({"review_id": review_id, "title": title, "author": author})
    
    print("\n📝 现在已经修改爬取逻辑为：")
    print("1. 爬取长评详情页 https://movie.douban.com/review/{review_id}/")
    print("2. 等待5秒，确保页面完全加载")
    print("3. 自动点击「展开阅读全文」按钮（如果存在）")
    print("4. 获取完整渲染后的页面HTML，解析正文")
    print("\n✅ 现在爬取到的长评text会是完整的，不会有截断和「加载中」字样！")
    print("\n🔧 测试方法：执行 review_body_crawl 任务爬取上面的review_id，然后去MongoDB检查text字段是否完整。")
    
